function renderAchievements(){ensureGame();const xp=state.game.xp,l=levelOf(xp),pct=Math.round((xp-nextLevelXP(l-1))/(nextLevelXP(l)-nextLevelXP(l-1))*100);root.innerHTML=`<div class="section-intro"><p class="eyebrow">DEINE LERNREISE</p><h1>Erfolge & Tagesmissionen</h1><p>Belohnungen für regelmäßiges, aktives Üben – ohne Vergleichsdruck. Level, XP und Abzeichen bleiben mit Konto geräteübergreifend erhalten.</p></div><section class="game-panel-grid"><div class="game-glance"><span class="big-medal">🏆</span><h2>Level ${l}: Wissensnavigator</h2><p>${xp} XP · noch ${nextLevelXP(l)-xp} XP bis Level ${l+1}</p><div class="progress-rail"><div class="progress-fill" style="--val:${pct}%"></div></div><div class="milestone-stats"><span>🔥 ${visibleStreak()} Tage Serie</span><span>⚡ ${state.game.battles} Duelle</span><span>🏅 ${state.game.badges.length}/${BADGES.length} Abzeichen</span></div></div><div class="game-glance"><h2>🎯 Missionen für heute</h2>${missionUI()}<p class="small muted">Jede erledigte Mission kannst du einmal pro Tag einlösen.</p></div></section><div class="section-bar"><h2>Deine Abzeichen</h2><p>${state.game.badges.length} von ${BADGES.length} freigeschaltet</p></div><div class="badge-gallery">${BADGES.map(([id,name,desc,emoji])=>`<article class="achievement ${state.game.badges.includes(id)?'earned':'locked'}"><div class="achievement-emoji">${emoji}</div><h3>${escapeHTML(name)}</h3><p>${escapeHTML(desc)}</p><span>${state.game.badges.includes(id)?'✓ Freigeschaltet':'🔒 Noch gesperrt'}</span></article>`).join('')}</div>`;}
function claimQuest(id){const stats=missionStats(),q={cards:[stats.reviews,10,65],sure:[stats.secure,4,75],arena:[stats.battles,1,95]}[id];if(!q||q[0]<q[1])return;const key=dayKey()+'-'+id;if(state.game.dailyClaimed[key])return;state.game.dailyClaimed[key]=true;earnXP(q[2],'Tagesmission');persist();render();}
const Q=window.KG_AG_CHALLENGES||[];
function shuffle(items){const a=items.slice();for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function stopChallenge(){if(challengeTimer)clearInterval(challengeTimer);challengeTimer=null;challenge=null;}
function renderChallenge(){if(!challenge){root.innerHTML=`<div class="section-intro"><p class="eyebrow">DIE WISSENSARENA</p><h1>⚡ Bist du bereit für ein Wissensduell?</h1><p>Beantworte 8 neue Multiple-Choice-Fragen zu KG und AG. Ein Mix aus Begriffen, kleinen Rechnungen und Gesetzesfällen. Für richtige Antworten gibt es XP und besondere Abzeichen.</p></div><section class="game-panel-grid"><div class="game-glance"><span class="big-medal">🎯</span><h2>Trainingsduell</h2><p>Ohne Zeitdruck · 8 Fragen · Lösungen erklärt</p><div class="toolbar"><button class="button primary" data-action="challenge-start-mode" data-mode="calm" data-topic="all">Mix starten</button><button class="button outline" data-action="challenge-start-mode" data-mode="calm" data-topic="kg">Nur KG</button><button class="button outline" data-action="challenge-start-mode" data-mode="calm" data-topic="ag">Nur AG</button></div></div><div class="game-glance"><span class="big-medal">⏱️</span><h2>Blitzduell</h2><p>90 Sekunden Gesamtzeit · Bonus bei perfekten 8/8</p><button class="button primary" data-action="challenge-start-mode" data-mode="timed" data-topic="all">Blitzrunde starten</button><p class="small muted">Barrierefreier Modus: Trainingsduell ohne Zeitlimit.</p></div></section>`;return;}
 if(challenge.finished){root.innerHTML=`<section class="arena-result"><span class="result-trophy">${challenge.correct>=7?'🏆':challenge.correct>=4?'✨':'🌱'}</span><p class="eyebrow">DUELL ABGESCHLOSSEN</p><h1>${challenge.correct} / ${challenge.questions.length} richtig</h1><p>Du hast ${challenge.xpEarned} XP verdient. Jede Runde trainiert andere Teilkompetenzen.</p><div class="toolbar" style="justify-content:center"><button class="button primary" data-action="challenge-start-mode" data-mode="calm" data-topic="${challenge.topic}">Noch ein Duell</button><button class="button outline" data-action="challenge-leave">Zur Lernarena</button></div></section>`;return;}
 const q=challenge.questions[challenge.index];const answered=challenge.selected!==null;root.innerHTML=`<div class="arena-wrap"><div class="section-bar"><div><p class="eyebrow">${challenge.mode==='timed'?'BLITZDUELL':'TRAININGSDUELL'}</p><h2>Wissensduell · ${challenge.topic==='kg'?'KG':challenge.topic==='ag'?'AG':'KG + AG'}</h2></div><button class="button ghost small" data-action="challenge-leave">Beenden ×</button></div><div class="arena-meta"><span>Frage ${challenge.index+1}/${challenge.questions.length}</span><span>🎯 ${challenge.correct} richtig</span><span id="countdown">${challenge.mode==='timed'?Math.max(0,Math.ceil((challenge.endAt-Date.now())/1000))+' s':'Ohne Zeitdruck'}</span></div><div class="study-progress"><div style="width:${100*challenge.index/challenge.questions.length}%"></div></div><article class="arena-question"><span class="kind-chip">${q[0]==='kg'?'KG-Recht':'AG-Recht'}</span><h2>${escapeHTML(q[1])}</h2><div class="choices">${q[2].map((s,i)=>`<button class="choice ${answered?(i===q[3]?'correct':i===challenge.selected?'wrong':''):''}" ${answered?'disabled':''} data-action="challenge-answer" data-choice="${i}"><span>${'ABCD'[i]}</span>${escapeHTML(s)}</button>`).join('')}</div>${answered?`<div class="arena-explain"><strong>${challenge.selected===q[3]?'✓ Richtig!':'✗ Noch nicht richtig'}</strong><p>${escapeHTML(q[4])}</p><button class="button primary" data-action="challenge-next">${challenge.index===challenge.questions.length-1?'Ergebnis ansehen':'Nächste Frage →'}</button></div>`:''}</article></div>`;}
function startChallenge(topic='all',mode='calm'){stopChallenge();const questions=shuffle(Q.filter(q=>topic==='all'||q[0]===topic)).slice(0,8);if(questions.length<8){notify('Zu wenige Fragen vorhanden.');return;}challenge={questions,index:0,selected:null,correct:0,topic,mode,finished:false,endAt:Date.now()+90000,xpEarned:0};page='challenge';render();if(mode==='timed'){challengeTimer=setInterval(()=>{if(!challenge||challenge.finished){clearInterval(challengeTimer);return;}const left=Math.max(0,Math.ceil((challenge.endAt-Date.now())/1000));const el=document.getElementById('countdown');if(el)el.textContent=left+' s';if(left<=0)finishChallenge();},250);}}
function chooseChallenge(idx){if(!challenge||challenge.finished||challenge.selected!==null||!Number.isInteger(idx)||idx<0||idx>3)return;challenge.selected=idx;if(idx===challenge.questions[challenge.index][3])challenge.correct++;renderChallenge();}
function nextChallenge(){if(!challenge||challenge.selected===null)return;challenge.index++;challenge.selected=null;if(challenge.index>=challenge.questions.length)finishChallenge();else renderChallenge();}
function finishChallenge(){if(!challenge||challenge.finished)return;if(challengeTimer)clearInterval(challengeTimer);challengeTimer=null;challenge.finished=true;challenge.xpEarned=challenge.correct*25+(challenge.correct===8?85:0);state.game.battles++;state.game.correctQuiz+=challenge.correct;state.activity.push({id:uid('arena'),type:'arena',ts:Date.now(),correct:challenge.correct,total:challenge.questions.length});earnXP(challenge.xpEarned,'Wissensduell');persist();fireConfetti();renderChallenge();}
async function apiRequest(action,data,method='POST'){
 const opts={method,credentials:'same-origin',headers:{'Accept':'application/json'}};
 if(method==='POST'){opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data||{});}
 const response=await fetch(API+'?action='+encodeURIComponent(action),opts);
 const json=await response.json().catch(()=>({error:'API liefert kein JSON. Netlify Functions aktivieren.'}));
 if(!response.ok){const e=new Error(json.error||`HTTP ${response.status}`);e.status=response.status;e.data=json;throw e;}
 return json;
}
function meaningfulGuest(s){return !!(s.activity?.length||s.cards?.some(c=>c.progress?.reviewCount||!c.builtIn)||s.decks?.some(d=>!d.builtIn));}
function mergeAccounts(local,cloud){if(!cloud)return clone(local);if(!local)return clone(cloud);const merged=clone(cloud);const decks=new Map(cloud.decks.map(d=>[d.id,d]));for(const d of local.decks||[])if(!decks.has(d.id)||(!d.builtIn&&d.updatedAt>(decks.get(d.id).updatedAt||0)))decks.set(d.id,d);merged.decks=[...decks.values()];const cards=new Map(cloud.cards.map(c=>[c.id,c]));for(const c of local.cards||[]){const old=cards.get(c.id);if(!old){cards.set(c.id,c);continue;}const p=c.progress||{},q=old.progress||{};if(Number(p.lastReviewedAt||0)>Number(q.lastReviewedAt||0))old.progress=p;if(c.updatedAt&&c.updatedAt>(old.updatedAt||0))Object.assign(old,{front:c.front,answer:c.answer,example:c.example,memory:c.memory,tags:c.tags,deckId:c.deckId,updatedAt:c.updatedAt});}merged.cards=[...cards.values()];const log=new Map();for(const a of (cloud.activity||[]).concat(local.activity||[])){log.set(a.id||`${a.ts}-${a.cardId||'g'}-${a.grade||a.type||''}`,a);}merged.activity=[...log.values()].sort((a,b)=>a.ts-b.ts).slice(-15000);merged.deletedBuiltIns=[...new Set([...(cloud.deletedBuiltIns||[]),...(local.deletedBuiltIns||[])])];merged.game={...newGame(),...(cloud.game||{})};merged.game.xp=Math.max(local.game?.xp||0,cloud.game?.xp||0);merged.game.days=[...new Set([...(cloud.game?.days||[]),...(local.game?.days||[])])].sort();merged.game.badges=[...new Set([...(cloud.game?.badges||[]),...(local.game?.badges||[])])];merged.game.dailyClaimed={...cloud.game?.dailyClaimed,...local.game?.dailyClaimed};merged.game.battles=Math.max(local.game?.battles||0,cloud.game?.battles||0);merged.game.correctQuiz=Math.max(local.game?.correctQuiz||0,cloud.game?.correctQuiz||0);merged.game.bestCombo=Math.max(local.game?.bestCombo||0,cloud.game?.bestCombo||0);merged.game.bestStreak=Math.max(local.game?.bestStreak||0,cloud.game?.bestStreak||0);merged.game.streak=Math.max(local.game?.streak||0,cloud.game?.streak||0);return merged;}
function scheduleSave(){if(!auth.user)return;auth.pending=true;paintTopHUD();clearTimeout(auth.timer);auth.timer=setTimeout(()=>{saveRemote();},900);}
async function saveRemote(){if(!auth.user||auth.saving)return;auth.saving=true;paintTopHUD();const capturedUser=auth.user.nickname;while(auth.pending&&auth.user?.nickname===capturedUser){auth.pending=false;const snapshot=clone(state);try{const result=await apiRequest('save',{state:snapshot,version:auth.version});auth.version=result.version;auth.changed=false;auth.serverAvailable=true;try{localStorage.removeItem(accountCacheKey()+'-dirty');localStorage.setItem(accountCacheKey()+'-version',auth.version||'');}catch{}}catch(e){if(e.status===409){auth.pending=false;const backup={...state};try{localStorage.setItem(accountCacheKey()+'-konflikt-backup',JSON.stringify(backup));}catch{}const overwrite=confirm('Der Lernstand wurde auf einem anderen Gerät verändert.\nOK: Diesen lokalen Stand in die Cloud speichern.\nAbbrechen: Den aktuelleren Cloud-Stand laden.\nEin Konflikt-Backup liegt im Browser.');if(overwrite){auth.version=e.data.version;auth.pending=true;}else{state=e.data.state||fresh();auth.version=e.data.version;ensureGame();localStorage.setItem(accountCacheKey(),JSON.stringify(state));render();} }else{auth.pending=true;auth.serverAvailable=false;notify('Cloud gerade nicht erreichbar. Lokal gesichert; bei Verbindung erneut synchronisieren.');break;}}}
 auth.saving=false;paintTopHUD();}
function openAccount(){switchAccountMode('login');if(auth.user){document.getElementById('accountForm').hidden=true;document.getElementById('signedInBox').hidden=false;document.getElementById('signedInBox').innerHTML=`<div class="account-ok"><span class="big-medal">☁</span><h3>Angemeldet als ${escapeHTML(auth.user.nickname)}</h3><p>Dein Lernstand wird über Netlify Blobs gesichert. Bei Offlinephasen lokal weitermachen und später synchronisieren.</p><button class="button primary" id="syncNow" type="button">Jetzt synchronisieren</button> <button class="button danger" id="logoutNow" type="button">Abmelden</button></div>`;document.getElementById('syncNow').onclick=()=>{auth.pending=true;saveRemote();};document.getElementById('logoutNow').onclick=logout;}else{document.getElementById('accountForm').hidden=false;document.getElementById('signedInBox').hidden=true;}document.getElementById('accountDialog').showModal();}
function switchAccountMode(mode){accountMode=mode;document.getElementById('tabLogin').classList.toggle('active',mode==='login');document.getElementById('tabRegister').classList.toggle('active',mode==='register');document.getElementById('accountDialogTitle').textContent=mode==='register'?'Konto erstellen':'Anmelden';document.getElementById('accountSubmit').textContent=mode==='register'?'Konto erstellen & sichern':'Anmelden & fortsetzen';document.getElementById('authHelp').textContent=mode==='register'?'Nickname frei wählbar; 10–128 Zeichen Passwort. Kein E-Mail-Reset vorhanden.':'Mit dem gleichen Nickname und Passwort kannst du jedes Gerät nutzen.';document.getElementById('accountForm').elements.password.autocomplete=mode==='register'?'new-password':'current-password';document.getElementById('accountFeedback').textContent='';}
async function submitAccount(e){e.preventDefault();if(auth.user)return;const f=e.currentTarget,nickname=f.elements.nickname.value.trim(),password=f.elements.password.value,merge=f.elements.takeLocal.checked;const btn=document.getElementById('accountSubmit');btn.disabled=true;document.getElementById('accountFeedback').textContent='Verbinde …';try{const guest=clone(state);const result=await apiRequest(accountMode,{nickname,password,...(accountMode==='register'?{state:merge?guest:fresh()}:{})});auth.user=result.user;auth.version=result.version||null;auth.serverAvailable=true;let draft=null;try{if(localStorage.getItem(accountCacheKey()+'-dirty'))draft=JSON.parse(localStorage.getItem(accountCacheKey())||'null');}catch{}state=accountMode==='register'?(merge?guest:fresh()):(draft?mergeAccounts(draft,merge&&meaningfulGuest(guest)?mergeAccounts(guest,result.state):result.state):merge&&meaningfulGuest(guest)?mergeAccounts(guest,result.state):result.state||fresh());ensureGame();auth.pending=false;auth.changed=false;try{localStorage.setItem(accountCacheKey(),JSON.stringify(state));localStorage.setItem(LAST_ACCOUNT,auth.user.nickname);localStorage.setItem(accountCacheKey()+'-version',auth.version||'');}catch{}if(accountMode==='login'&&((merge&&meaningfulGuest(guest))||draft))scheduleSave();document.getElementById('accountDialog').close();notify(`Willkommen, ${auth.user.nickname}! Cloud-Synchronisierung aktiv.`);render();}catch(ex){document.getElementById('accountFeedback').textContent=ex.message||'Anmeldung fehlgeschlagen.';}finally{btn.disabled=false;}}
async function logout(){if(auth.pending)await saveRemote();if(auth.pending){notify('Noch nicht synchronisiert. Bitte Verbindung herstellen oder vor der Abmeldung ein JSON-Backup exportieren.');return;}const key=accountCacheKey();try{await apiRequest('logout',{});}catch{}try{localStorage.removeItem(LAST_ACCOUNT);localStorage.removeItem(key);localStorage.removeItem(key+'-dirty');localStorage.removeItem(key+'-version');}catch{}auth.user=null;auth.version=null;auth.pending=false;auth.saving=false;state=load();ensureGame();document.getElementById('accountDialog').close();notify('Abgemeldet. Gast-Lernstand dieses Browsers ist wieder aktiv.');render();}
async function initAuth(){paintTopHUD();try{
 const r=await apiRequest('me',null,'GET');auth.serverAvailable=true;
 if(r.signedIn){
   auth.user=r.user;auth.version=r.version||null;
   let local=null,wasDirty=false;
   try{local=JSON.parse(localStorage.getItem(accountCacheKey())||'null');wasDirty=!!localStorage.getItem(accountCacheKey()+'-dirty');}catch{}
   state=wasDirty&&local?mergeAccounts(local,r.state||fresh()):r.state||fresh();
   ensureGame();try{localStorage.setItem(LAST_ACCOUNT,auth.user.nickname);localStorage.setItem(accountCacheKey(),JSON.stringify(state));localStorage.setItem(accountCacheKey()+'-version',auth.version||'');}catch{}
   if(wasDirty&&local){auth.pending=true;scheduleSave();}
   render();
 }else{
   if(auth.user){notify('Deine Sitzung ist abgelaufen. Melde dich erneut an, um weiter zu synchronisieren.');auth.user=null;auth.version=null;auth.pending=false;state=load();ensureGame();render();}
   paintTopHUD();
 }
 }catch{
  auth.serverAvailable=false;
  if(!auth.user){
    try{const nickname=localStorage.getItem(LAST_ACCOUNT);if(nickname){const key=KEY+'-konto-'+nickname.normalize('NFKC').toLocaleLowerCase('de-DE');const cached=JSON.parse(localStorage.getItem(key)||'null');if(cached&&Array.isArray(cached.cards)){auth.user={nickname};auth.version=localStorage.getItem(key+'-version')||null;auth.pending=!!localStorage.getItem(key+'-dirty');state=cached;ensureGame();render();}}}catch{}
  }
  paintTopHUD();
 }
}
